"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant2 from "./components/announcement-banners/variants/03-rotating-ribbon";
const variants = {"rotating-ribbon": Variant2};
export interface ArtemisAnnouncementBannersProps { className?: string; variant?: "rotating-ribbon"; }
export function ArtemisAnnouncementBanners({ className, variant = "rotating-ribbon" }: ArtemisAnnouncementBannersProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { useEffect, useRef, useState } from "react";
import { AnimatePresence, animate, motion, useInView, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
const announcements = [
    { badge: "New release", message: "The summer collection is ready to explore", action: "See what is new" },
    { badge: "Early access", message: "Join the first group shaping our next chapter", action: "Request an invite" },
    { badge: "Live session", message: "A practical conversation about calmer product work", action: "Save your place" },
] as const;
export default function AnnouncementBannersRotatingRibbon() {
    const reduced = useReducedMotion();
    const root = useRef<HTMLDivElement>(null);
    const sweep = useRef<HTMLSpanElement>(null);
    const sweepEntered = useRef(false);
    const inView = useInView(root, { margin: "100px" });
    const [visible, setVisible] = useState(true);
    const [pageVisible, setPageVisible] = useState(true);
    const [index, setIndex] = useState(0);
    useEffect(() => {
        const updateVisibility = () => setPageVisible(!document.hidden);
        updateVisibility();
        document.addEventListener("visibilitychange", updateVisibility);
        return () => document.removeEventListener("visibilitychange", updateVisibility);
    }, []);
    useEffect(() => {
        if (reduced || !visible || !pageVisible || !inView)
            return;
        const timer = window.setInterval(() => setIndex((current) => (current + 1) % announcements.length), 5200);
        return () => window.clearInterval(timer);
    }, [reduced, visible, pageVisible, inView]);
    useEffect(() => {
        if (reduced || !visible || !pageVisible || !inView)
            return;
        if (!sweepEntered.current) {
            sweepEntered.current = true;
            return;
        }
        const strip = sweep.current;
        if (!strip)
            return;
        let playing = true;
        const animation = animate("translate3d(-140%, 0px, 0px)", "translate3d(280%, 0px, 0px)", {
            duration: 6, ease: "linear", repeat: Infinity, repeatDelay: 1.5,
            onUpdate: (transform) => { if (playing)
                strip.style.transform = transform; },
        });
        return () => {
            playing = false;
            animation.stop();
        };
    }, [reduced, visible, pageVisible, inView]);
    const announcement = announcements[index];
    return (<>
      <div ref={root} className="art:w-full art:bg-background">
        {(!reduced || visible) && <AnimatePresence initial={false}>
        {visible && <motion.aside initial={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: reduced ? 0 : 0.45, ease: ARTEMIS_EASE_OUT }} aria-label="Announcements" className="art:relative art:overflow-hidden art:bg-foreground art:text-background">
          <span ref={sweep} aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-y-0 art:left-0 art:w-1/3 art:bg-background/8 art:blur-2xl"/>
          <div className="art:relative art:mx-auto art:flex art:min-h-16 art:w-full art:max-w-7xl art:items-center art:gap-3 art:px-4 art:py-3 art:pr-14 art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:pr-16 art:@min-[1024px]/artemis:px-8">
            <div aria-live="polite" className="art:flex art:min-w-0 art:flex-1 art:items-center art:justify-center art:gap-3">
              <AnimatePresence initial={false} mode="wait">
              <motion.div key={index} initial={{ opacity: reduced ? 1 : 0, filter: reduced ? "blur(0px)" : "blur(6px)", y: reduced ? 0 : 8 }} animate={{ opacity: 1, filter: "blur(0px)", y: 0 }} exit={{ opacity: 0, filter: "blur(6px)", y: -8 }} transition={{ duration: reduced ? 0 : 0.38, ease: ARTEMIS_EASE_OUT }} className="art:flex art:min-w-0 art:flex-col art:items-center art:gap-2 art:text-center art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:text-left">
                <span className="art:shrink-0 art:rounded-full art:bg-background/12 art:px-2.5 art:py-1 art:font-medium art:text-xs">
                  {announcement.badge}
                </span>
                <p className="art:text-pretty art:font-medium art:text-sm art:leading-5">
                  {announcement.message}
                </p>
                <motion.a whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:gap-1.5 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:shrink-0 art:border-background/20 art:bg-background/10 art:px-2.5 art:text-background art:hover:bg-background/15 art:h-9 art:rounded-full" href="#" tabIndex={0}>
                  {announcement.action}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-3.5" aria-hidden="true">
                    <path d="M5 12h14"/>
                    <path d="m12 5 7 7-7 7"/>
                  </svg>
                </motion.a>
              </motion.div>
              </AnimatePresence>
            </div>
            <motion.button onClick={() => setVisible(false)} whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:absolute art:right-3 art:size-9 art:text-background/65 art:hover:bg-background/10 art:hover:text-background art:@min-[640px]/artemis:right-5 art:h-9 art:rounded-full" aria-label="Dismiss announcements" tabIndex={0}>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-4" aria-hidden="true">
                <path d="M18 6 6 18"/>
                <path d="m6 6 12 12"/>
              </svg>
            </motion.button>
          </div>
        </motion.aside>}
        </AnimatePresence>}
      </div>
    </>);
}
